async function appendScreenshotPreview(item, screenshotId) { const screenshot = await getScreenshot(screenshotId); if (!screenshot) return; const figure = document.createElement('figure'); figure.className = 'screenshot-preview'; const image = document.createElement('img'); const text = screenshot.ocrText || (screenshot.ocrState === 'processing' ? 'OCR is processing this screenshot.' : 'Screenshot captured locally. OCR is not enabled.'); image.alt = text; const url = URL.createObjectURL(screenshot.blob); image.src = url; image.addEventListener('load', () => URL.revokeObjectURL(url), { once: true }); figure.append(image); item.append(figure); }
function transcriptIconButton(icon, label) { const button = document.createElement('button'); button.type = 'button'; button.className = 'icon-button transcript-icon-button'; button.setAttribute('aria-label', label); button.title = label; const symbol = document.createElement('span'); symbol.setAttribute('aria-hidden', 'true'); symbol.textContent = icon; const text = document.createElement('span'); text.className = 'sr-only'; text.textContent = label; button.append(symbol, text); return button; }
function renderTranscript() { const query = ui['transcript-search'].value.toLowerCase(); const sources = selectedTranscriptSources(); const showSpeakerLabels = ui['show-speaker-labels'].checked; const showTimestamps = ui['show-timestamps'].checked; const showSources = ui['show-sources'].checked; const shown = segments.filter((segment) => sources.has(segment.source) && (!query || segment.text.toLowerCase().includes(query))); ui['transcript-list'].replaceChildren(); shown.forEach((segment) => { const item = document.createElement('li'); item.className = 'transcript-segment'; const label = document.createElement('span'); label.className = 'segment-label'; label.textContent = [showTimestamps ? formatTime(segment.start) : '', showSources ? sourceName(segment.source) : ''].filter(Boolean).join(' | '); label.hidden = !label.textContent; const text = document.createElement('span'); text.className = 'segment-text'; text.textContent = segment.text; if (audioSegment(segment)) { const select = document.createElement('input'); select.type = 'checkbox'; select.className = 'segment-selection'; select.checked = selectedSegmentIds.has(segment.id); select.setAttribute('aria-label', `Select audio block at ${formatDateTime(segment.start)} for speaker assignment`); select.addEventListener('change', () => { if (select.checked) selectedSegmentIds.add(segment.id); else selectedSegmentIds.delete(segment.id); }); item.append(select); if (showSpeakerLabels) { const speakers = document.createElement('span'); speakers.className = 'speaker-label'; const names = participantNames(segment); const anonymous = (segment.automaticSpeakerSlots || []).map(slotName); speakers.textContent = names.length ? names.join(', ') : anonymous.join(', '); speakers.hidden = !speakers.textContent; item.append(speakers); } } const editButton = transcriptIconButton('✎', 'Edit transcript text'); const edit = document.createElement('textarea'); edit.hidden = true; edit.value = segment.text; edit.setAttribute('aria-label', `Transcript text from ${sourceName(segment.source)} at ${formatDateTime(segment.start)}`); editButton.addEventListener('click', () => { edit.hidden = !edit.hidden; if (!edit.hidden) edit.focus(); }); edit.addEventListener('change', async () => { segment.text = safeText(edit.value); text.textContent = segment.text; await putSegment(segment); }); item.append(label, text, editButton, edit); if (segment.screenshotId && segment.source === 'screen') { const downloadButton = transcriptIconButton('⇩', 'Download screenshot'); downloadButton.addEventListener('click', async () => { const screenshot = await getScreenshot(segment.screenshotId); if (screenshot) download(screenshot.blob, `${fileSafeName(session?.name || 'screenshot')}-${screenshot.capturedAt}.webp`, 'image/webp'); }); item.append(downloadButton); void appendScreenshotPreview(item, segment.screenshotId); } ui['transcript-list'].append(item); }); ui['empty-transcript'].hidden = Boolean(shown.length); }

async function openSavedSession(saved) { if (session) return setSessionStatus('Stop the current session before opening a saved transcript.'); segments = await getSegments(saved.id); viewedSession = saved; diarizationSessionId = saved.id; activeSpeakerAssignments = saved.speakerAssignments || {}; detectedSpeakerSlots.clear(); segments.flatMap((segment) => segment.automaticSpeakerSlots || []).forEach((slot) => detectedSpeakerSlots.add(slot)); selectedSegmentIds.clear(); segments.sort((a, b) => a.start - b.start); ui['session-name'].value = saved.name || defaultSessionName(new Date(saved.startedAt)); renderTranscript(); renderDetectedSpeakers(); setSessionStatus(`Opened saved transcript “${saved.name || 'Untitled call'}”.`); }
async function renderSavedSessions() { const savedSessions = (await getSessions()).sort((a, b) => b.startedAt - a.startedAt); ui['saved-session-list'].replaceChildren(); for (const saved of savedSessions) { const row = document.createElement('tr'); const name = document.createElement('th'); name.scope = 'row'; name.textContent = saved.name || defaultSessionName(new Date(saved.startedAt)); const started = document.createElement('td'); started.textContent = formatDateTime(saved.startedAt); const status = document.createElement('td'); status.textContent = saved.status || 'saved'; const actions = document.createElement('td'); const open = document.createElement('button'); open.type = 'button'; open.textContent = 'Open'; open.addEventListener('click', () => openSavedSession(saved)); const remove = document.createElement('button'); remove.type = 'button'; remove.textContent = 'Delete'; remove.addEventListener('click', () => requestSessionDelete(saved)); actions.append(open, remove); row.append(name, started, status, actions); ui['saved-session-list'].append(row); } }
ui['transcript-search'].addEventListener('input', renderTranscript);
ui['show-speaker-labels'].addEventListener('change', () => { localStorage.setItem('localBrowserTranscriberShowSpeakerLabels', String(ui['show-speaker-labels'].checked)); renderTranscript(); });
ui['show-timestamps'].addEventListener('change', () => { localStorage.setItem('localBrowserTranscriberShowTimestamps', String(ui['show-timestamps'].checked)); renderTranscript(); });
ui['show-sources'].addEventListener('change', () => { localStorage.setItem('localBrowserTranscriberShowSources', String(ui['show-sources'].checked)); renderTranscript(); });
ui['enable-speaker-separation'].addEventListener('change', () => { speakerSeparationEnabled = ui['enable-speaker-separation'].checked; localStorage.setItem('localBrowserTranscriberSpeakerSeparation', String(speakerSeparationEnabled)); if (speakerSeparationEnabled && !speakerModelReady) diarizerWorker.postMessage({ type: 'load' }); ui['speaker-model-status'].textContent = speakerSeparationEnabled ? 'Preparing the local speaker model. Speaker separation will start when it is ready.' : 'Automatic speaker separation is off.'; });
ui['add-participant'].addEventListener('click', () => addParticipant(ui['participant-name'].value));
ui['participant-name'].addEventListener('keydown', (event) => { if (event.key === 'Enter') { event.preventDefault(); addParticipant(ui['participant-name'].value); } });
ui['run-participant-command'].addEventListener('click', runParticipantCommand);
ui['participant-command'].addEventListener('keydown', (event) => { if (event.key === 'Enter') { event.preventDefault(); runParticipantCommand(); } });
ui['add-speaker-to-selected'].addEventListener('click', () => applyPersonToSelected('add'));
ui['remove-speaker-from-selected'].addEventListener('click', () => applyPersonToSelected('remove'));
ui['clear-speakers-from-selected'].addEventListener('click', () => applyPersonToSelected('clear'));
ui['enable-microphone'].addEventListener('change', () => ui['enable-microphone'].checked ? enableMic() : pipelines.get('microphone')?.stop()); ui['share-system-audio'].addEventListener('change', () => ui['share-system-audio'].checked ? shareSystemAudio() : stopScreenCapture()); ui['start-session'].addEventListener('click', startSession); ui['pause-session'].addEventListener('click', togglePause); ui['stop-session'].addEventListener('click', stopSession);
ui['new-session'].addEventListener('click', async () => { if (session) await stopSession(); segments = []; selectedSegmentIds.clear(); ui['session-name'].value = defaultSessionName(); renderTranscript(); setSessionStatus('Ready for a new session.'); });
function requestDelete(model) { if (session?.modelId === model.id) return setStatus('Stop the active session before removing its model.'); pendingDelete = { type: 'model', value: model }; ui['delete-heading'].textContent = 'Remove downloaded model?'; ui['confirm-delete'].textContent = 'Remove model'; ui['delete-message'].textContent = `Remove ${model.name} from browser-managed model storage? Other models and transcript sessions will be kept.`; ui['delete-dialog'].showModal(); }
function requestOcrDelete() { pendingDelete = { type: 'ocr' }; ui['delete-heading'].textContent = 'Remove local OCR?'; ui['confirm-delete'].textContent = 'Remove OCR'; ui['delete-message'].textContent = 'Remove the locally downloaded OCR model from browser-managed storage? Existing screenshots and OCR text will be kept.'; ui['delete-dialog'].showModal(); }
function requestSessionDelete(saved) { pendingDelete = { type: 'session', value: saved }; ui['delete-heading'].textContent = 'Delete saved transcript?'; ui['confirm-delete'].textContent = 'Delete transcript'; ui['delete-message'].textContent = `Delete “${saved.name || 'Untitled call'}” and all of its transcript text from this browser? This cannot be undone.`; ui['delete-dialog'].showModal(); }
function requestParticipantDelete(person) { pendingDelete = { type: 'participant', value: person }; ui['delete-heading'].textContent = 'Remove saved person?'; ui['confirm-delete'].textContent = 'Remove person'; ui['delete-message'].textContent = `Remove ${person.name} from saved people and all transcript speaker labels in this browser? Transcript text and audio are kept.`; ui['delete-dialog'].showModal(); }
ui['delete-dialog'].addEventListener('close', async () => { if (ui['delete-dialog'].returnValue !== 'confirm' || !pendingDelete) { pendingDelete = null; return; } const target = pendingDelete; pendingDelete = null; if (target.type === 'session') { await deleteSegments(target.value.id); await deleteScreenshots(target.value.id); await removeSession(target.value.id); if (!session) { segments = []; selectedSegmentIds.clear(); renderTranscript(); } await renderSavedSessions(); setSessionStatus('Saved transcript deleted from this browser.'); return; } if (target.type === 'participant') { await removeParticipantFromSegments(target.value.id); await removeParticipant(target.value.id); selectedSegmentIds.clear(); await renderParticipants(); renderTranscript(); ui['participant-status'].textContent = `${target.value.name} was removed from saved people and transcript labels.`; return; } if (target.type === 'ocr') { const cache = await caches.open('local-browser-transcriber-ocr-v1'); await Promise.all(OCR_ASSETS.map((path) => cache.delete(new URL(path, document.baseURI).href))); localStorage.removeItem('localBrowserTranscriberOcrEnabled'); setOcrToggle(false); await renderDownloadedModels(); return; } const model = target.value; const cache = await caches.open('transformers-cache'); const keys = await cache.keys(); await Promise.all(keys.filter((request) => request.url.includes(model.repo)).map((request) => cache.delete(request))); await removeModel(model.id); if (activeModel === model.id) activeModel = null; await renderModels({ rebuild: true }); await renderDownloadedModels(); refreshDiagnostics(); });

function download(content, name, type) { const link = document.createElement('a'); link.href = URL.createObjectURL(content instanceof Blob ? content : new Blob([content], { type })); link.download = name; link.click(); setTimeout(() => URL.revokeObjectURL(link.href), 1000); }
function clock(ms) { const seconds = Math.floor(ms / 1000); return `${String(Math.floor(seconds / 3600)).padStart(2, '0')}:${String(Math.floor(seconds / 60) % 60).padStart(2, '0')}:${String(seconds % 60).padStart(2, '0')}`; }
function fileSafeName(name) { return name.replaceAll(/[^a-z0-9._-]+/gi, '-').replaceAll(/^-|-$/g, '') || 'transcript'; }
function transcriptProvenance() { const model = findModel(activeModel || selectedModel); return { app: 'CallScribe', website: 'https://projects.timdixon.net/CallScribe/', model: model?.name || 'Not recorded', language: selectedLanguage || 'Not recorded', audioProcessing: audioProcessingEnabled ? 'On' : 'Off', voiceSettings: { ...voiceProcessing } }; }
function provenanceText() { const details = transcriptProvenance(); return `Generated with ${details.app}\nWebsite: ${details.website}\nModel: ${details.model}\nSpoken language: ${details.language}\nAudio processing: ${details.audioProcessing}\nVoice settings: high-pass ${details.voiceSettings.highPass} Hz; low-pass ${details.voiceSettings.lowPass} Hz; threshold ${details.voiceSettings.threshold} dB; ratio ${details.voiceSettings.ratio}:1`; }
function renderTranscriptProvenance() { let summary = $('transcript-provenance'); if (!summary) { summary = document.createElement('p'); summary.id = 'transcript-provenance'; summary.className = 'transcript-provenance'; document.querySelector('.transcript-controls').after(summary); } summary.hidden = !session; summary.textContent = `${transcriptProvenance().model} · ${selectedLanguage || 'English'} · Audio processing ${audioProcessingEnabled ? 'on' : 'off'} · Generated with CallScribe`; }
function speakerText(segment) { const names = participantNames(segment); const labels = names.length ? names : (segment.automaticSpeakerSlots || []).map(slotName); return labels.length ? ` | ${labels.join(', ')}` : ''; }
function exportText(items = segments) { return `${provenanceText()}\n\nTranscript\n${items.map((segment) => `${formatDateTime(segment.start)} | ${sourceName(segment.source)}${speakerText(segment)} | ${segment.text}`).join('\n')}`; }
function currentSessionId() { return session?.id || segments.find((segment) => segment.sessionId)?.sessionId; }
function blobToDataUrl(blob) { return new Promise((resolve, reject) => { const reader = new FileReader(); reader.onload = () => resolve(reader.result); reader.onerror = () => reject(reader.error || new Error('Unable to read screenshot.')); reader.readAsDataURL(blob); }); }
async function sessionScreenshots() { const sessionId = currentSessionId(); return sessionId ? (await getScreenshots(sessionId)).sort((a, b) => a.capturedAt - b.capturedAt) : []; }
async function exportMarkdown() { const screenshots = await sessionScreenshots(); const screenshotsById = new Map(screenshots.map((screenshot) => [screenshot.id, screenshot])); const exported = new Set(); const title = session?.name || ui['session-name'].value.trim() || 'Transcript'; const lines = [`# ${title}`, '', '## Generated with', '', provenanceText(), '', `Exported: ${formatDateTime(Date.now())}`, '']; for (const segment of segments) { lines.push(`## ${formatDateTime(segment.start)} — ${sourceName(segment.source)}${speakerText(segment)}`, '', segment.text || '', ''); if (segment.source !== 'screen' || !segment.screenshotId || exported.has(segment.screenshotId)) continue; const screenshot = screenshotsById.get(segment.screenshotId); if (!screenshot) continue; exported.add(screenshot.id); lines.push(`![Screenshot captured ${formatDateTime(screenshot.capturedAt)}](${await blobToDataUrl(screenshot.blob)})`, ''); if (screenshot.ocrText) lines.push(`Screenshot OCR: ${screenshot.ocrText}`, ''); }
  for (const screenshot of screenshots) { if (exported.has(screenshot.id)) continue; lines.push(`## Screenshot — ${formatDateTime(screenshot.capturedAt)}`, '', `![Screenshot captured ${formatDateTime(screenshot.capturedAt)}](${await blobToDataUrl(screenshot.blob)})`, ''); if (screenshot.ocrText) lines.push(`Screenshot OCR: ${screenshot.ocrText}`, ''); }
  download(lines.join('\n'), `${fileSafeName(title)}.md`, 'text/markdown;charset=utf-8'); setSessionStatus(`Exported Markdown with ${screenshots.length} embedded screenshot${screenshots.length === 1 ? '' : 's'}.`); }
async function downloadScreenshots() { const screenshots = await sessionScreenshots(); const title = fileSafeName(session?.name || ui['session-name'].value); if (!screenshots.length) return setSessionStatus('There are no screenshots in this transcript to download.'); screenshots.forEach((screenshot, index) => download(screenshot.blob, `${title}-screenshot-${String(index + 1).padStart(3, '0')}.webp`, 'image/webp')); setSessionStatus(`Downloading ${screenshots.length} screenshot${screenshots.length === 1 ? '' : 's'}.`); }
function subtitle(kind) { const header = kind === 'vtt' ? 'WEBVTT\n\n' : ''; return header + segments.map((s, index) => `${kind === 'srt' ? `${index + 1}\n` : ''}${clock(s.start - s.sessionStartedAt)} --> ${clock(s.end - s.sessionStartedAt)}\n[${sourceName(s.source)}${speakerText(s)}] ${s.text}\n`).join('\n'); }
ui['export-transcript'].addEventListener('click', () => { const title = fileSafeName(session?.name || ui['session-name'].value); const format = ui['export-format'].value; if (format === 'markdown') return exportMarkdown().catch((error) => setSessionStatus(`Markdown export failed: ${error.message}`)); if (format === 'screenshots') return downloadScreenshots().catch((error) => setSessionStatus(`Screenshot download failed: ${error.message}`)); if (format === 'json') return download(JSON.stringify({ provenance: transcriptProvenance(), segments }, null, 2), `${title}.json`, 'application/json'); if (format === 'srt') return download(`1\n00:00:00,000 --> 00:00:03,000\n${provenanceText().replaceAll('\n', ' | ')}\n\n${subtitle('srt')}`, `${title}.srt`, 'text/plain'); if (format === 'vtt') return download(`WEBVTT\n\nNOTE ${provenanceText().replaceAll('\n', ' | ')}\n\n${subtitle('vtt').replace('WEBVTT\n\n', '')}`, `${title}.vtt`, 'text/vtt'); return download(exportText(), `${title}.txt`, 'text/plain'); });
async function refreshDiagnostics() { const estimate = await navigator.storage?.estimate?.(); const values = [['Browser', navigator.userAgent], ['WebGPU', navigator.gpu ? 'Available' : 'Unavailable'], ['WebAssembly', typeof WebAssembly === 'object' ? 'Available' : 'Unavailable'], ['Active model', activeModel ? findModel(activeModel).name : 'None'], ['Audio pipelines', pipelines.size], ['Storage use', estimate?.usage ? bytes(estimate.usage) : 'Not reported'], ['Storage quota', estimate?.quota ? bytes(estimate.quota) : 'Not reported'], ['Last error', 'None']]; ui.diagnostics.replaceChildren(...values.flatMap(([term, description]) => { const dt = document.createElement('dt'); dt.textContent = term; const dd = document.createElement('dd'); dd.textContent = description; return [dt, dd]; })); }
$('export-diagnostics').addEventListener('click', () => download(ui.diagnostics.innerText, 'local-browser-transcriber-diagnostics.txt', 'text/plain'));
initialise().catch((error) => failDownload(`Initialisation failed: ${error.message}`));
